import {C as store} from './index-BLVOhKhN.js?v=20261004-progress2';
import {recordRecoveries,weekOf} from './memory-stars-state-20261004.js';
const KEY='lux-memory-stars-v1',PENDING='lux-memory-stars-pending-v1';
function read(key){if(key===KEY&&store.getState().memoryStars)return store.getState().memoryStars;try{return JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{return {}}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));if(key===KEY)store.setState({memoryStars:value});return true}catch{return false}}
const subject=()=>location.pathname.split('/').filter(Boolean)[1]||'study';
function arm(){if(!/^\/study\/[^/]+\/practise/.test(location.pathname))return;write(PENDING,{...read(PENDING),[subject()]:Date.now()});}
