function refresh(){const result=document.querySelector('[data-memory-recovered-ids]');if(result){let ids=[];try{ids=JSON.parse(result.dataset.memoryRecoveredIds)}catch{}if(ids.length){const pending=read(PENDING),at=pending[subject()];if(at&&Date.now()-at<7*86400000){const update=recordRecoveries(read(KEY),subject(),ids,new Date(at).toISOString());if(write(KEY,update.state)){delete pending[subject()];write(PENDING,pending)}}let banner=result.querySelector('.memory-star-result');const sig=JSON.stringify(ids);if(!banner){banner=document.createElement('div');banner.className='memory-star-result';banner.setAttribute('role','status');result.prepend(banner)}if(banner.dataset.signature!==sig){banner.dataset.signature=sig;banner.innerHTML=star+`<div><strong>${ids.length} memory ${ids.length===1?'star':'stars'}</strong><p>${ids.length===1?'Old mistake':'Old mistakes'} answered independently.</p><a href="/garden">View collection →</a></div>`}const heading=result.querySelector('h2');if(heading)heading.style.display='none';for(const p of result.querySelectorAll(':scope > p'))if(/^You independently answered/.test(p.textContent))p.style.display='none'}}
 let panel=document.getElementById('memory-star-collection');if(location.pathname.replace(/\/$/,'')!=='/garden'){panel?.remove();return}const main=document.querySelector('main');if(!main)return;if(!panel){panel=document.createElement('section');panel.id='memory-star-collection';panel.className='memory-collection';panel.setAttribute('aria-label','Memory star collection');main.append(panel)}const state=read(KEY),weeks=Object.entries(state.weeks||{}).sort(([a],[b])=>b.localeCompare(a)),week=weekOf(Date.now()),current=state.weeks?.[week],sig=JSON.stringify(weeks);if(panel.dataset.signature===sig)return;panel.dataset.signature=sig;panel.innerHTML=`<div class="memory-piece ${current?'':'memory-locked'}">${lantern}<div><p class="memory-kicker">THIS WEEK’S COLLECTION</p><h2>Memory Star Lantern</h2><p>${current?`${current.count} old ${current.count===1?'mistake':'mistakes'} answered independently.`:'Recover an old mistake from memory to collect this week’s lantern.'}</p><span>${current?'Collected':'Not collected yet'}</span></div></div>${weeks.length?'<details><summary>Collection · '+weeks.length+' '+(weeks.length===1?'week':'weeks')+'</summary><div class="memory-archive"></div></details>':''}`;const archive=panel.querySelector('.memory-archive');for(const [date,value]of weeks){const row=document.createElement('p');row.textContent=`Week of ${date.split('-').reverse().join('/')} · ${value.count} memory ${value.count===1?'star':'stars'}`;archive?.append(row)}}
const css=document.createElement('style');css.textContent='.memory-star-result{display:flex;gap:16px;align-items:center;margin:12px 0;padding:14px;border-radius:18px;background:#fff5d9;color:#173e50}.memory-star-result>svg{width:72px;height:72px;flex-shrink:0;animation:memory-light .8s ease-out}.memory-star-result strong{font-size:21px}.memory-star-result p{margin:4px 0;font-size:15px}.memory-star-result a{display:inline-flex;min-height:44px;align-items:center;text-decoration:underline}.memory-collection{margin:24px 0;padding:20px;border:1px solid #c5d3c5;border-radius:22px;background:#fffdf7}.memory-piece{display:flex;align-items:center;gap:18px}.memory-piece>svg{width:120px;height:140px;flex-shrink:0}.memory-piece h2{font-size:26px;font-family:Georgia,serif}.memory-piece p{font-size:16px;margin:6px 0}.memory-piece span{display:inline-block;padding:4px 10px;border-radius:20px;background:#e6eee0}.memory-kicker{font-size:12px!important;letter-spacing:.1em}.memory-locked>svg{opacity:.4;filter:grayscale(1)}.memory-collection summary{cursor:pointer;min-height:44px;align-content:center}.memory-archive p{margin:8px 0;font-size:15px}@keyframes memory-light{from{opacity:.2;transform:scale(.6) rotate(-15deg)}to{opacity:1;transform:scale(1)}}.cx-quiet .memory-star-result>svg{animation:none}@media(prefers-reduced-motion:reduce){.memory-star-result>svg{animation:none}}@media(max-width:600px){.memory-piece>svg{width:80px;height:105px}.memory-piece h2{font-size:22px}.memory-star-result>svg{width:56px;height:56px}}';document.head.append(css);
